      ${profiles.length ? `<div class="links">${profiles.slice(0, 8).map((u, i) => ext(u, `profile ${i + 1} ↗`)).join('')}${profiles.length > 8 ? `<span class="muted small">+${profiles.length - 8} more</span>` : ''}</div>` : ''}
      <span class="muted" style="font:11px var(--mono)">evidence #${Number(e.id)}</span>
    </div></details>`;
  }
  function signalsCard(all, byId, win) {
    if (!all.length) return '';
    const byScore = (a, b) => (num(b.score) || 0) - (num(a.score) || 0);
    const forCo = all.filter((s) => s.polarity !== 'against' && fired(s)).sort(byScore);
    const guards = all.filter((s) => s.polarity === 'against' && fired(s)).sort(byScore);
    const quiet = all.filter((s) => !fired(s));
    const one = (s) => `<div class="sig ${fired(s) ? '' : 'off'}"${s.evidence_id ? ` id="ev-${Number(s.evidence_id)}"` : ''}>
        <div class="sig-top"><div class="sig-name">${esc(sigName(s.name))}<span class="label">${esc(FAMILY[s.family] || s.family || '')}</span></div>
        <div class="meter"><span class="num">${fix2(s.score)}</span><span class="bar"><i style="width:${clamp01(s.score) * 100}%"></i></span></div></div>
        <p>${esc(tidy(s.summary))}</p>${receipt(byId.get(s.evidence_id))}</div>`;
    return `<section class="card o-sig" aria-labelledby="h-sig">
      <div class="card-head"><h2 id="h-sig">Evidence</h2><span class="label">${win ? 'Latest window' : plural(all.length, 'check')}</span></div>
      <h3 class="label group-label">Points to coordination <span style="white-space:nowrap">· ${forCo.length} of ${all.length} signals</span></h3>
      ${forCo.length ? `<div>${forCo.map(one).join('')}</div>` : '<p class="muted">No coordination signal fired.</p>'}
      ${guards.length ? `<h3 class="label group-label">Organic safeguards that held</h3><div>${guards.map(one).join('')}</div>` : ''}
      ${quiet.length ? `<details class="fold"><summary>${plural(quiet.length, 'check')} found nothing: ${esc(quiet.map((s) => sigName(s.name).toLowerCase()).join(', '))}</summary><div>${quiet.map(one).join('')}</div></details>` : ''}
    </section>`;
  }

  function timingCard(c, handles, win) {
    const sig = c.signals || {};
    const nd = sig.null_distribution;
    const tl = Array.isArray(sig.timeline) ? sig.timeline.filter((p) => num(p.t) != null) : [];
    const parts = [];
    if (nd && Array.isArray(nd.counts) && Array.isArray(nd.bin_edges) && nd.counts.length) {
      const max = Math.max(...nd.counts, 1);
      const lo = nd.bin_edges[0], hi = nd.bin_edges[nd.bin_edges.length - 1];
      const obs = Math.min(hi, Math.max(lo, num(nd.observed) || 0));
      const left = ((obs - lo) / (hi - lo || 1)) * 100;
      const worlds = nd.worlds || nd.counts.reduce((a, b) => a + b, 0);
      const k = nd.worlds_at_least_observed;
      const timingP = sig.null_model && sig.null_model.p_value;
      parts.push(`<div class="hist" role="img" aria-label="Synchrony in ${worlds} shuffled worlds; the real accounts score ${fix2(nd.observed)}.">
          ${nd.counts.map((n) => `<i style="height:${(n / max) * 100}%"></i>`).join('')}
          <span class="obs" style="left:calc(${left}% - 1px)"></span></div>
        <div class="axis" aria-hidden="true"><span>${fix2(lo)}</span><span>${fix2(hi)}</span></div>
        <p class="muted small" style="margin-top:4px">Horizontal axis: share of the accounts’ actions that fall in the same tight burst.</p>
        <div class="key"><span><i style="background:#5a5650"></i>Shuffled timing</span><span><i style="background:var(--shill)"></i>Real accounts: ${fix2(nd.observed)}</span></div>
        <p class="chart-caption">We shuffled each account’s activity in time ${worlds.toLocaleString()} times.${k != null ? ` <strong>${k.toLocaleString()}</strong> of those shuffles were as synchronised as the real accounts` : ''}${timingP != null ? ` (timing p = ${pval(timingP)}).` : '.'}</p>`);
    }

