[
  {
    "file": "api/routes/analyze.py",
    "line": 51,
    "summary": "bsky_target only recognises bsky.app links that start with http(s), because lookup.urls.classify returns None for anything else, so a post link pasted without a scheme is never looked up as a post.",
    "failure_scenario": "url='bsky.app/profile/did:plc:abc/post/3n27wevn47t2i' (as copied from many share sheets): classify returns None, so bsky is None and clusters_for_post never runs. checkable_url then normalises it to https://bsky.app/... and drops it because bsky.app is in SKIP_HOSTS, so there is no web check either. The response is a silent 'insufficient' even when the post is in cluster #682, which is the #15 defect this PR claims to fix."
  },
