import dataclasses, sys
from signals.config import DEFAULT
from signals.detect import detect
from signals.score import AccountInfo
from signals.synth import empty_window, inject
from signals.textnorm import text_hash
from signals.window import WindowData, WPost

M = [  # (handle, display, bio, age, followers)  live cluster 682/859 members
 ("techlawjdsupra.bsky.social","Tech Law News","... A JD Supra feed www.jdsupra.com",627,206),
 ("m-and-a-jdsupra.bsky.social","Mergers & Acquisitions Watch","... A JD Supra news feed www.jdsupra.com",627,96),
 ("european-union-law.bsky.social","European Union Legal Watch","... A JD Supra news feed www.jdsupra.com",627,36),
 ("ai-law-news.bsky.social","Artificial Intelligence Watch","... A JD Supra law feed www.jdsupra.com",627,160),
 ("frank-jdsupra.bsky.social","Frank","Lead Engineer at JD Supra.",723,156),
]
def window(seed=0):
    base = empty_window(seed=seed)
    wd = WindowData(start=base.start, end=base.end)
    for j, slug in enumerate(["be-kind-rewind-8542956", "the-bug-october-2026-4316556"]):
        for i in range(5):
            t = base.start + 100 + 400*j + i
            wd.posts.append(WPost(uri=f"at://did:plc:jd{i}/app.bsky.feed.post/{j}", did=f"did:plc:jd{i}",
                t=t, created_t=t, text=f"title {slug}", text_hash=text_hash(f"title {slug}"),
                embed_urls=[f"https://jdsupra.com/legalnews/{slug}"], langs=["en"]))
    return inject(base, type("S",(object,),{"posts":wd.posts,"actions":[], "accounts":{}})()) if False else _merge(base, wd)
def _merge(base, wd):
    base.posts.extend(wd.posts); return base
def info(mode):
    out = {}
    for i,(h,dn,bio,age,f) in enumerate(M):
        d=f"did:plc:jd{i}"
        a = AccountInfo(did=d, handle=h, display_name=dn, description=bio, age_days=float(age), followers=f, follows=50, posts_count=5000, description_len=len(bio), has_avatar=True)
        if mode=="nobio": a = dataclasses.replace(a, description=None)
        if mode=="new": a = dataclasses.replace(a, age_days=3.0)
        out[d]=a
    return out
for mode in ["none","full","nobio","new"]:
    wd = window()
    acc = None if mode=="none" else info(mode)
    res = detect(wd, (lambda dids: {d: acc[d] for d in dids if d in acc}) if acc else None, DEFAULT)
    hits=[c for c in res.clusters if any(m.startswith("did:plc:jd") for m in c.members)]
    for c in hits:
        g={s.name:s.score for s in c.signals if s.polarity=="against"}
        print(mode, c.status, "fired", c.families_fired, "guard", c.guard_score, g, "templ", [s.score for s in c.signals if s.name=="templated_handles"])
    if not hits: print(mode, "no cluster")

